/// Returns true if `v` starts with prefix `p` according to the problem's definition.
/// That is:
/// - if `p` is empty, returns true;
/// - otherwise, returns true if `v` has length at least `p.len()`
///   and for all indices i < p.len(), v[i] == p[i].
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        true
    } else if v.len() < p.len() {
        false
    } else {
        // Check element-wise equality for prefix length
        v.iter().take(p.len()).zip(p.iter()).all(|(a, b)| a == b)
    }
}

/// Returns a new vector containing exactly the sequences from `xs`
/// that start with the prefix `p`.
/// The relative order from the original vector is preserved.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect()
}